    status = status,
    startedAt = startedAt,
    activity = activity,
    kind = activity.kinds.first(),
    distanceUnit = units,
    log = log,
)

private fun draft(
    activity: CardioActivity = CardioActivity.OUTDOOR_RUN,
    units: DistanceUnit = DistanceUnit.KM,
) = CardioLogDraft(activity = activity, distanceUnit = units)

class TempLogDraftCheck {
    @Test
    fun durationReadsHoursMinutesAndSeconds() {
        val d = draft().with(CardioLogField.DURATION, "33:12")
        assertEquals(1992, d.toRequest().durationSeconds)
        val h = draft().with(CardioLogField.DURATION, "1:12:40")
        assertEquals(4360, h.toRequest().durationSeconds)
    }

    @Test
    fun durationRefusesOtherShapes() {
        listOf("45", "1:75", "abc").forEach {
            assertEquals("use h:mm:ss", draft().with(CardioLogField.DURATION, it).errors()[CardioLogField.DURATION])
        }
    }

    @Test
    fun paceIsDerivedWhenBlankAndNeverSent() {
        val d =
            draft()
                .with(CardioLogField.DURATION, "33:12")
                .with(CardioLogField.DISTANCE, "5.02")
        assertEquals("6:37", d.derived(CardioLogField.AVG_PACE))
        assertNull(d.toRequest().avgPaceSeconds)
    }

    @Test
    fun speedIsDerivedForRides() {
        val d =
            draft(CardioActivity.OUTDOOR_RIDE)
                .with(CardioLogField.DURATION, "1:12:40")
                .with(CardioLogField.DISTANCE, "38.6")
        assertEquals("31.9", d.derived(CardioLogField.AVG_SPEED))
    }

    @Test
    fun theRowerDerivesPerFiveHundredMetres() {
        val d =
            draft(CardioActivity.ROWER)
                .with(CardioLogField.DURATION, "8:24")
                .with(CardioLogField.DISTANCE, "2000")
        assertEquals("2:06", d.derived(CardioLogField.AVG_PACE))
    }

    @Test
    fun maxBelowAvgIsAnError() {
        val d =
            draft()
                .with(CardioLogField.AVG_HEART_RATE, "148")
                .with(CardioLogField.MAX_HEART_RATE, "139")
        assertEquals("max heart rate is below average", d.errors()[CardioLogField.MAX_HEART_RATE])
    }

    @Test
    fun rowerCadenceOutOfRangeNamesTheRange() {
        assertEquals(
            "between 10 and 60 spm",
            draft(CardioActivity.ROWER).with(CardioLogField.AVG_CADENCE, "8").errors()[CardioLogField.AVG_CADENCE],
        )
    }

    @Test
    fun anErrorShowsOnlyOnceTheFieldWasLeft() {
        val d = draft().with(CardioLogField.DURATION, "abc")
        assertTrue(d.errors().containsKey(CardioLogField.DURATION))
        assertNull(d.shownError(CardioLogField.DURATION))
        assertEquals("use h:mm:ss", d.left(CardioLogField.DURATION).shownError(CardioLogField.DURATION))
    }

    @Test
    fun durationPrefillsFromTheClockRoundedDown() {
        val w =
            workout(
                status = WorkoutStatus.IN_PROGRESS,
                startedAt = Instant.parse("2026-10-20T18:31:00Z"),
            )
        val d = CardioLogDraft.fresh(w, Instant.parse("2026-10-20T19:12:06.900Z"))
        assertEquals("41:06", d.text(CardioLogField.DURATION))
    }

    @Test
    fun rowerDistanceIsMetresWhateverTheUnit() {
        val d =
            draft(CardioActivity.ROWER)
                .with(CardioLogField.DURATION, "30:00")
                .with(CardioLogField.DISTANCE, "7120")
        assertEquals(CardioDistance(7120.0, DistanceUnit.M), d.toRequest().distance)
    }

    @Test
    fun ofRecomputesDerivedPace() {
        val log =
            CardioLog(
                durationSeconds = 4360,
                distance = CardioDistance(5.02, DistanceUnit.KM),
                derivedAvgPaceSeconds = 869,
            )
        val d = CardioLogDraft.of(workout(log = log))
        assertEquals("", d.text(CardioLogField.AVG_PACE))
        assertEquals("14:29", d.derived(CardioLogField.AVG_PACE))
    }

    @Test
    fun typedPaceKillsDerived() {
        val d =
            draft()
                .with(CardioLogField.DURATION, "33:12")
                .with(CardioLogField.DISTANCE, "5.02")
                .with(CardioLogField.AVG_PACE, "6:30")
        assertNull(d.derived(CardioLogField.AVG_PACE))
        assertEquals(390, d.toRequest().avgPaceSeconds)
    }

    @Test
    fun canSubmitNeedsDurationAndNoErrors() {
        assertTrue(!draft().canSubmit)
        val ok = draft().with(CardioLogField.DURATION, "33:12")
        assertTrue(ok.canSubmit)
        assertTrue(!draft().with(CardioLogField.DURATION, "abc").canSubmit)
    }
}
